pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 unlockTime, uint256 putAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0));
        vm.assume(unlockTime > block.timestamp);
        vm.assume(putAmount >= 1 ether);
        vm.assume(collectAmount > 0 && collectAmount <= putAmount);

        // Fund the test contract to send ETH
        vm.deal(caller, putAmount);
        vm.deal(address(this), 10 ether);

        // Call Put to set unlockTime
        vm.prank(caller);
        c.Put{value: putAmount}(unlockTime);

        // Record the unlockTime before Collect
        uint256 unlockTimeBefore = c.Acc(caller).unlockTime;

        // Warp to after unlockTime
        vm.warp(unlockTime + 1);

        // Call Collect
        vm.prank(caller);
        c.Collect(collectAmount);

        // Assert: unlockTime unchanged
        uint256 unlockTimeAfter = c.Acc(caller).unlockTime;
        assertTrue(unlockTimeBefore == unlockTimeAfter, "unlockTime changed");
    }
}

