pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint _unlockTime, uint _putAmount, uint _collectAmount) public {
        // Bound the amounts to avoid overflow issues
        vm.assume(_putAmount < 1e30);
        vm.assume(_collectAmount < 1e30);

        // Deal the caller some ether
        address caller = address(0x1234);
        vm.deal(caller, _putAmount + _collectAmount + 1 ether);

        // Perform a put to seed the balance
        vm.prank(caller);
        c.Put{value: _putAmount}(_unlockTime);

        // Try collect and capture revert
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, _collectAmount));

        // The general rule: if collect reverts, then (acc.balance < MinSum) OR (acc.balance < _collectAmount) OR (block.timestamp <= acc.unlockTime)
        // For the bugged version, the first condition flips to (acc.balance >= MinSum) which breaks the invariant
        if (!success) {
            // We can only observe public getters; acc.balance is not directly readable, but we can check if MinSum is met via Acc
            // Since we fuzzed and put the exact amount, we can derive condition from the call parameters instead
            // But must use only public info: after Put, Acc[caller].balance = _putAmount (if no selfdestruct etc)
            // We'll use a simpler formulation: revert can only happen if the original conditions fail (one of them)
            // The bug only flips MinSum condition; we can't directly observe balance, so we assert the invariant over parameters
            // However the rule must be general over fuzz params. We accept that the test may have false positives in non-buggy version.
            // We'll encode: if !success, then either _putAmount < 1 ether or _putAmount < _collectAmount or block.timestamp <= _unlockTime
            // Since we called Put with _putAmount, acc.balance = _putAmount
            bool cond1 = _putAmount < 1 ether;     // MinSum
            bool cond2 = _putAmount < _collectAmount;
            bool cond3 = block.timestamp <= _unlockTime;
            assertTrue(cond1 || cond2 || cond3);
        } else {
            // If success, the bug may also cause it incorrectly, but our property is about revert case
            // We don't need an else
        }
    }
}

